# Let me check if the pattern relates to symmetry from the opposite side
# The right region has 5s and the left has 6s
# Look at positions that are symmetric relative to center

input_grid = [
    [0, 0, 6, 0, 0, 1, 5, 5, 5, 0, 0],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 5],
    [0, 0, 0, 0, 0, 1, 5, 5, 5, 5, 0],
    [0, 0, 0, 0, 6, 1, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 0]
]

# Get left and right regions
left_region = [row[:5] for row in input_grid]
right_region = [row[7:] for row in input_grid]  # skip column 5 and 6, use 7 onwards

print("Left region:")
for row in left_region:
    print(row)

print("\nRight region (cols 7-10):")
for row in right_region:
    print(row)

# Check positions with value 6 in left region
print("\nPositions with value 6 in left region:")
for i in range(5):
    for j in range(5):
        if left_region[i][j] == 6:
            print(f"  ({i}, {j})")

# Check positions with value 5 in right region  
print("\nPositions with value 5 in right region:")
for i in range(5):
    for j in range(5):
        if right_region[i][j] == 5:
            print(f"  ({i}, {j})")

# OR pattern - combine places where either has non-zero
print("\nOR pattern (positions with non-0 in either):")
output = [[0 for _ in range(5)] for _ in range(5)]
for i in range(5):
    for j in range(5):
        if left_region[i][j] != 0 or right_region[i][j] != 0:
            output[i][j] = left_region[i][j] if left_region[i][j] != 0 else right_region[i][j]

print(output)

